import{_ as t,o as r,c as l,a2 as e}from"./chunks/framework.DIWxYxwh.js";const i="/assets/ecm-cross-section.CDnZbTjh.jpg",o="/assets/ecm-exploded-view.D6fd_I88.jpg",s="/assets/ecm-capsule-photo.kXKpKlbh.jpg",n="/assets/mems-internal-structure.D66eGoUh.jpg",h="/assets/mems-package-acoustic-port.BjSlVNpo.jpg",d="/assets/mems-analog-microphone.Dprj5QaM.jpg",p="/assets/mems-pdm-microphone.C_CfIZmq.jpg",c="/assets/mems-i2s-microphone.CLcMl-r0.jpg",m="/assets/microphone-acoustic-path-seal.AFlHPAvP.png",g="/assets/speaker-microphone-acoustic-isolation.DTEMq_4h.png",E=JSON.parse('{"title":"麦克风基础知识与结构设计","description":"","frontmatter":{},"headers":[],"relativePath":"语音交互/声学硬件结构.md","filePath":"语音交互/声学硬件结构.md","lastUpdated":1792058828000}'),u={name:"语音交互/声学硬件结构.md"};function _(b,a,q,M,f,P){return r(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="麦克风基础知识与结构设计" tabindex="-1">麦克风基础知识与结构设计 <a class="header-anchor" href="#麦克风基础知识与结构设计" aria-label="Permalink to &quot;麦克风基础知识与结构设计&quot;">​</a></h1><p>本文介绍常见的驻极体麦克风（ECM）和硅 MEMS 麦克风的基本结构、工作原理、接口区别与选型方法，并整理麦克风阵列的关键结构设计要求。</p><h2 id="一、常见麦克风结构" tabindex="-1">一、常见麦克风结构 <a class="header-anchor" href="#一、常见麦克风结构" aria-label="Permalink to &quot;一、常见麦克风结构&quot;">​</a></h2><h3 id="_1-驻极体麦克风-ecm" tabindex="-1">1. 驻极体麦克风（ECM） <a class="header-anchor" href="#_1-驻极体麦克风-ecm" aria-label="Permalink to &quot;1. 驻极体麦克风（ECM）&quot;">​</a></h3><p><img src="'+i+'" alt="驻极体麦克风剖面示例：振膜、背板与 JFET。此图把电荷画在背板侧"></p><p><img src="'+o+'" alt="驻极体麦克风爆炸图：振膜、驻极体膜、背极板与 JFET"></p><p><img src="'+s+'" alt="带两根引脚的驻极体麦克风胶囊"></p><h4 id="内部结构" tabindex="-1">内部结构 <a class="header-anchor" href="#内部结构" aria-label="Permalink to &quot;内部结构&quot;">​</a></h4><p>典型 ECM 主要由以下部分组成：</p><ul><li><strong>振膜：</strong> 接收声波并产生机械振动。</li><li><strong>背板：</strong> 与振膜构成电容式换能结构。</li><li><strong>驻极体材料：</strong> 提供长期保持的电荷，可以位于振膜或背板侧，不能一律理解成带电背板。</li><li><strong>FET 缓冲电路：</strong> 将高阻抗信号转换为便于后级处理的电信号。</li></ul><h4 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h4><p>声波推动振膜振动，改变振膜与背板之间的电容。在驻极体提供的电场条件下，电容变化转化为电信号，再由内部 FET 缓冲电路输出模拟音频信号。</p><h4 id="主要特点" tabindex="-1">主要特点 <a class="header-anchor" href="#主要特点" aria-label="Permalink to &quot;主要特点&quot;">​</a></h4><ul><li>成本较低，技术成熟。</li><li>通常需要外部偏置电路。</li><li>一般输出模拟音频信号。</li><li>对模拟前端、电源噪声和 PCB 布线有一定要求。</li></ul><p><strong>常见应用：</strong> 通话设备、传统录音设备、低成本语音采集模块。</p><h3 id="_2-硅-mems-麦克风-硅麦" tabindex="-1">2. 硅 MEMS 麦克风（硅麦） <a class="header-anchor" href="#_2-硅-mems-麦克风-硅麦" aria-label="Permalink to &quot;2. 硅 MEMS 麦克风（硅麦）&quot;">​</a></h3><p><img src="'+n+'" alt="硅 MEMS 麦克风封装、声学腔体与电容读出"></p><p><img src="'+h+'" alt="硅麦贴片封装：顶部声孔，以及底部焊盘和声孔"></p><h4 id="内部结构-1" tabindex="-1">内部结构 <a class="header-anchor" href="#内部结构-1" aria-label="Permalink to &quot;内部结构&quot;">​</a></h4><p>典型电容式硅 MEMS 麦克风主要包括：</p><ul><li><strong>微型振膜：</strong> 感知声压变化。</li><li><strong>固定背板：</strong> 与振膜构成电容式换能结构。</li><li><strong>声学腔体：</strong> 为声压传递和振膜运动提供空间。</li><li><strong>ASIC 芯片：</strong> 负责信号放大，以及根据型号实现模数转换或数字处理。</li></ul><h4 id="工作原理-1" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理-1" aria-label="Permalink to &quot;工作原理&quot;">​</a></h4><p>声波通过声孔进入麦克风，推动微型振膜振动并引起电容变化。内部 ASIC 将其转换为可用的音频信号，输出形式取决于具体器件。</p><h4 id="常见接口" tabindex="-1">常见接口 <a class="header-anchor" href="#常见接口" aria-label="Permalink to &quot;常见接口&quot;">​</a></h4><p><img src="'+d+'" alt="模拟硅麦贴片封装：正面金属盖，底部声孔与焊盘"></p><p><strong>模拟硅麦：</strong> 输出模拟音频信号，需要通过外部 ADC 或音频 Codec 转换为数字数据。</p><p><img src="'+p+'" alt="PDM 数字麦克风模块，引脚含 CLK、DAT、SEL"></p><p><img src="'+c+'" alt="I²S 数字麦克风模块，引脚含 WS、SCK、DO"></p><p><strong>数字硅麦：</strong> 常见输出为 PDM。PDM 是脉冲密度调制的 1 位数据流，主控需要提供时钟，并在后级完成抽取滤波后才能得到 PCM 音频。I²S 是串行数字音频接口，传输的是已经按声道和采样组织好的数字音频，两者不能互相替代。选型时应确认主控支持的接口类型、时钟要求和数据格式。</p><h4 id="主要特点-1" tabindex="-1">主要特点 <a class="header-anchor" href="#主要特点-1" aria-label="Permalink to &quot;主要特点&quot;">​</a></h4><ul><li>体积小，适合 SMT 贴片生产。</li><li>便于多麦克风阵列集成。</li><li>有模拟输出和数字输出型号。</li><li>仍需关注供电、声孔、PCB 布局和接口设计。</li></ul><p><strong>常见应用：</strong> 手机、无线耳机、智能音箱、会议终端和语音交互设备。</p><h3 id="_3-ecm-与硅-mems-的区别" tabindex="-1">3. ECM 与硅 MEMS 的区别 <a class="header-anchor" href="#_3-ecm-与硅-mems-的区别" aria-label="Permalink to &quot;3. ECM 与硅 MEMS 的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>驻极体麦克风（ECM）</th><th>硅 MEMS 麦克风</th></tr></thead><tbody><tr><td>换能方式</td><td>驻极体电容式</td><td>微机电传感结构，常见为电容式</td></tr><tr><td>常见封装</td><td>胶囊式</td><td>微型贴片式</td></tr><tr><td>输出类型</td><td>通常为模拟信号</td><td>模拟或数字信号</td></tr><tr><td>外围电路</td><td>通常需要偏置及模拟前端</td><td>取决于器件类型与接口</td></tr><tr><td>阵列集成</td><td>可以实现</td><td>通常更便于小型化集成</td></tr><tr><td>典型应用</td><td>通话、传统录音</td><td>智能终端、多麦克风阵列</td></tr></tbody></table><h3 id="_4-选型建议" tabindex="-1">4. 选型建议 <a class="header-anchor" href="#_4-选型建议" aria-label="Permalink to &quot;4. 选型建议&quot;">​</a></h3><ul><li><strong>选择 ECM：</strong> 预算有限、需要模拟音频采集，且设备空间允许使用胶囊式麦克风。</li><li><strong>选择硅 MEMS：</strong> 需要小型化、贴片生产、多麦克风阵列，或希望使用数字音频接口。</li></ul><p>硅 MEMS 并不必然比 ECM 音质更好，实际效果取决于器件指标、声学结构、外围电路和信号处理算法。</p><h2 id="二、麦克风结构设计" tabindex="-1">二、麦克风结构设计 <a class="header-anchor" href="#二、麦克风结构设计" aria-label="Permalink to &quot;二、麦克风结构设计&quot;">​</a></h2><p>麦克风的实际拾音效果不仅取决于传感器本身，还受到外壳开孔、声腔、密封、隔振及扬声器结构的影响。</p><h3 id="_1-拾音孔与声学通道" tabindex="-1">1. 拾音孔与声学通道 <a class="header-anchor" href="#_1-拾音孔与声学通道" aria-label="Permalink to &quot;1. 拾音孔与声学通道&quot;">​</a></h3><p><img src="'+m+'" alt="顶部进音硅麦、底部进音硅麦和驻极体麦克风的密封与声路"></p><h4 id="设计要求" tabindex="-1">设计要求 <a class="header-anchor" href="#设计要求" aria-label="Permalink to &quot;设计要求&quot;">​</a></h4><ul><li>麦克风声孔应与外壳拾音孔准确对齐。</li><li>密封硅胶应紧贴结构表面，避免漏声和不必要的空腔。</li><li>尽量缩短声音从外壳开孔到麦克风声孔的传播路径。</li><li>避免胶水、泡棉等材料遮挡拾音孔。</li></ul><p><strong>开孔尺寸关系：</strong></p><p>结构开孔直径 ≥ 密封硅胶孔径 ≥ PCB 或麦克风声孔直径。</p><p>该关系可作为初步结构设计参考，实际尺寸还应结合器件封装和密封方式确定。</p><h4 id="拾音孔径深比" tabindex="-1">拾音孔径深比 <a class="header-anchor" href="#拾音孔径深比" aria-label="Permalink to &quot;拾音孔径深比&quot;">​</a></h4><p>径深比定义为 δ = D / L。</p><p>其中：</p><ul><li>D：拾音孔直径。</li><li>L：拾音孔深度。</li></ul><p>参考设计建议：</p><ul><li>径深比 δ ≥ 1/3。</li><li>推荐径深比 δ ≥ 1/2。</li><li>可优先评估直径约 1.3～1.5 mm 的开孔方案。</li></ul><p>例如，孔径为 1.3 mm 时，若按径深比不小于 1/3 的经验值设计，孔深宜控制在约 3.9 mm 以内。</p><p>上述数值属于结构设计参考，不是适用于所有麦克风的统一标准。孔径、孔深和声腔共同影响声学阻抗及频率响应，应以器件资料和整机测试结果为准。</p><p><strong>设计目的：</strong> 避免狭长声道和不合理声腔引起声学共振，减少频率响应异常。</p><h3 id="_2-麦克风密封与隔振" tabindex="-1">2. 麦克风密封与隔振 <a class="header-anchor" href="#_2-麦克风密封与隔振" aria-label="Permalink to &quot;2. 麦克风密封与隔振&quot;">​</a></h3><p>设计时应重点关注：</p><ul><li><strong>密封：</strong> 防止设备内部的声音通过缝隙直接进入麦克风。</li><li><strong>隔振：</strong> 减少外壳、PCB 或其他机械部件振动传递至麦克风。</li><li><strong>声腔：</strong> 避免不必要的封闭空间和狭长通道。</li><li><strong>装配一致性：</strong> 控制硅胶压缩量、开孔偏差和胶水溢出。</li></ul><p>密封和隔振需要同时考虑，但两者作用不同：密封主要控制声泄漏，隔振主要控制机械振动传递。</p><h3 id="_3-扬声器与麦克风的隔离" tabindex="-1">3. 扬声器与麦克风的隔离 <a class="header-anchor" href="#_3-扬声器与麦克风的隔离" aria-label="Permalink to &quot;3. 扬声器与麦克风的隔离&quot;">​</a></h3><p><img src="'+g+'" alt="扬声器声音应经外部空气到达麦克风，避免腔内串扰"></p><p>对于带扬声器的语音设备，应尽量降低扬声器声音经设备内部结构直接传递至麦克风的程度。</p><h4 id="设计建议" tabindex="-1">设计建议 <a class="header-anchor" href="#设计建议" aria-label="Permalink to &quot;设计建议&quot;">​</a></h4><ol><li><strong>合理布局：</strong> 在结构允许的情况下增大扬声器与麦克风的距离。</li><li><strong>独立腔体：</strong> 优先采用具有独立音腔的扬声器结构，并做好腔体密封与减振。</li><li><strong>隔音处理：</strong> 对无法采用独立音腔的结构，可评估增加隔音材料或隔离结构。</li><li><strong>接口密封：</strong> 对扬声器出音口与外壳的接合位置进行密封，避免声音泄漏至内部。</li><li><strong>材料选择：</strong> 可评估发泡硅胶、聚氨酯泡棉等材料；材料硬度、厚度和压缩量应结合装配公差验证。</li></ol><p>泡棉厚度应根据结构间隙、压缩率和密封要求确定，不宜直接套用固定倍数。材料选择也不应仅依据名称判断，应通过整机测试验证隔音、耐久性和装配可靠性。</p><h4 id="整机验证" tabindex="-1">整机验证 <a class="header-anchor" href="#整机验证" aria-label="Permalink to &quot;整机验证&quot;">​</a></h4><ul><li>扬声器最大工作音量下，检查麦克风输入是否发生削波或截幅。</li><li>检查播放声音对录音、唤醒和语音识别的影响。</li><li>验证密封结构是否存在漏声。</li><li>结合回声消除算法进行整机测试。</li></ul><h2 id="三、以语音交互设备为例" tabindex="-1">三、以语音交互设备为例 <a class="header-anchor" href="#三、以语音交互设备为例" aria-label="Permalink to &quot;三、以语音交互设备为例&quot;">​</a></h2><p>完整的语音采集系统通常包含三个层次：</p><ol><li><strong>麦克风硬件：</strong> 采集声音。</li><li><strong>音频前端：</strong> 完成信号调理、采样和多通道同步。</li><li><strong>语音处理算法：</strong> 实现波束形成、降噪、回声消除和语音识别。</li></ol><p>对于远场会议拾音等应用，多麦克风阵列需要与声学结构和算法协同设计。具体产品采用的麦克风类型、数量和布局，应以对应型号的公开技术资料为准。</p><h2 id="四、参考资料" tabindex="-1">四、参考资料 <a class="header-anchor" href="#四、参考资料" aria-label="Permalink to &quot;四、参考资料&quot;">​</a></h2><ul><li><a href="https://www.xfyun.cn/doc/solutions/hardwareUniversal/CAEdesign.html" target="_blank" rel="noreferrer">科大讯飞开放平台：麦克风阵列设计参考</a></li><li><a href="https://invensense.tdk.com/" target="_blank" rel="noreferrer">TDK InvenSense：MEMS 麦克风技术资料</a></li><li><a href="https://www.analog.com/en/resources.html" target="_blank" rel="noreferrer">Analog Devices：音频与数字 MEMS 麦克风技术资料</a></li></ul><h2 id="五、总结" tabindex="-1">五、总结 <a class="header-anchor" href="#五、总结" aria-label="Permalink to &quot;五、总结&quot;">​</a></h2><p>ECM 与硅 MEMS 的主要区别在于换能实现方式、封装形式及输出接口。硬件设计时，应优先确认器件规格和主控接口，再重点检查拾音孔、声腔、密封、隔振和扬声器隔离。</p><p>对于多麦克风语音设备，最终性能需要通过声学设计、音频链路和算法的协同验证来保证。</p>',76)])])}const x=t(u,[["render",_]]);export{E as __pageData,x as default};
